            let reconcile_state = s.ongoing_reconciles[cr_key];
            let resp_o = if input.recv is Some {
                if input.recv->0.content.is_APIResponse() {
                    Some(ResponseContent::KubernetesResponse(input.recv->0.content.get_APIResponse_0()))
